"""Read the signed original piano control export and its physical note index."""
from collections import defaultdict
import csv
import json
from pathlib import Path
from source_native_notation import score, sha


def read_control(job):
    # This book and its unmodified export are already generated by piano recovery.
    config=job/"source-piano-context.json"
    if not config.is_file():
        return None
    meta=json.loads(config.read_text("utf8"))
    native=meta.get("native_recovery",{})
    path=native.get("source_book")
    signature=native.get("source_book_sha256")
    folder=meta.get("evidence_directory")
    if not path or not folder or not signature or sha(Path(path))!=signature:
        return None
    ctrl=Path(folder)/"native-core/control"
    if not all((ctrl/x).is_file() for x in ("result.mxl","head-ledger.tsv")):
        return None
    block=defaultdict(list)
    with (ctrl/"head-ledger.tsv").open(encoding="utf8",newline="") as stream:
        for row in csv.DictReader(stream,delimiter="\t"):
            if row["head"]!="0" and row["repeat_copy"]=="false":
                block[row["part"],row["measure"],int(row["note_index"])].append(row)
    return Path(path),score(ctrl/"result.mxl"),{k:v[0] for k,v in block.items() if len(v)==1}
